{"command":"cd /tmp &&
for v in get list watch; do
  cmd="kubectl auth can-i $v configmaps -n default --as=system:serviceaccount:default:config-reader";
  printf "%-35s -> " "$cmd"; kubectl $cmd
done
echo '--- HTTP to API ---';
kubectl exec -n default app-5c4859756d-8qpk7 -- sh -c 'wget -qO- https://kubernetes.default.svc 2>&1 | head -4; wget -qO- http://kubernetes.default.svc 2>&1 | head -4; wget -qO- https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config 2>&1 | head -6'; echo 'HTTP err=$?'
echo '--- http to /api/v1 gives a server response'"}

